mapper.select:
select p.server_id as serverId, p.host_name as scanHostName, p.os_name as scanOsName, p.os_version as scanOsVersion,
    p.kernel_version as scanKernelVersion, p.detected_ports as scanPorts, date_format(p.scan_time, '%Y-%m-%d %H:%i:%s') as scanTime
from sup_server_scan_profile p join sup_server s on s.server_id=p.server_id and s.site_id=p.site_id where p.site_id=#{siteId}

select (select count(*) from sup_server where site_id=#{siteId} and inet_aton(server_address)=inet_aton(#{address}))
  + (select count(*) from sup_hardware_asset where site_id=#{siteId}
      and (inet_aton(ip_address)=inet_aton(#{address}) or inet_aton(manage_ip)=inet_aton(#{address})))
